runtime_assertions:
const input = { name: ' Alice ', age: '20', email: 'alice@example.com' };
assert.equal(subject.parseUserJson('{').kind, 'invalid-json');
assert.equal(subject.parseUserJson('{}').kind, 'invalid-data');
assert.deepEqual(subject.parseUserJson(JSON.stringify(input)), { kind: 'valid', data: { name: 'Alice', age: 20, email: 'alice@example.com', role: 'member' } });
assert.equal(subject.UserSchema.safeParse({ ...input, extra: true }).success, false);
assert.equal(subject.UserSchema.safeParse({ ...input, name: '   ' }).success, false);
assert.equal(subject.UserSchema.safeParse({ ...input, age: 16 }).success, false, 'underage input must be rejected');
const parsed = subject.UserSchema.parse(input);
assert.equal(parsed.name, 'Alice');
assert.equal(input.name, ' Alice ');
assert.equal(input.age, '20');
assert.deepEqual(subject.DefaultsSchema.parse({}), { name: 'Anonymous' });
assert.equal(subject.CountsSchema.safeParse({ a: '2' }).success, false);
assert.deepEqual(subject.CountsSchema.parse({ a: 2 }), { a: 2 });
assert.equal((await subject.UsernameSchema.safeParseAsync('available')).success, true);
assert.equal((await subject.UsernameSchema.safeParseAsync('taken')).success, false);
const iso = '2024-01-15T10:30:00.000Z';
const date = subject.DateCodec.decode(iso);
assert.equal(date instanceof Date, true);
assert.equal(subject.DateCodec.encode(date), iso);
assert.equal(subject.DateCodec.safeDecode('not-a-date').success, false);
assert.equal(subject.DateCodec.safeEncode(new Date(NaN)).success, false);
assert.throws(() => subject.UserSchema.transform(() => { throw new Error('callback failure'); }).safeParse(input), /callback failure/);
